import{_ as e,o as a,c as t,ac as _}from"./chunks/framework.B-3EzaJq.js";const h=JSON.parse('{"title":"中国共产党第十三届中央委员会委员、候补委员名单","description":"","frontmatter":{"prev":{"text":"中国共产党第十三次全国代表大会关于中央纪律检查委员会工作报告的决议","link":"./中国共产党第十三次全国代表大会关于中央纪律检查委员会工作报告的决议"},"next":{"text":"中央顾问委员会委员名单","link":"./中央顾问委员会委员名单"}},"headers":[],"relativePath":"13/中国共产党第十三届中央委员会委员、候补委员名单.md","filePath":"13/中国共产党第十三届中央委员会委员、候补委员名单.md"}'),r={name:"13/中国共产党第十三届中央委员会委员、候补委员名单.md"};function n(i,p,l,o,s,c){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="中国共产党第十三届中央委员会委员、候补委员名单" tabindex="-1">中国共产党第十三届中央委员会委员、候补委员名单 <a class="header-anchor" href="#中国共产党第十三届中央委员会委员、候补委员名单" aria-label="Permalink to &quot;中国共产党第十三届中央委员会委员、候补委员名单&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#中央委员">中央委员</a></li><li><a href="#中央候补委员">中央候补委员</a></li></ul></nav><div class="text-center"><h2 id="中央委员" tabindex="-1">中央委员 <a class="header-anchor" href="#中央委员" aria-label="Permalink to &quot;中央委员&quot;">​</a></h2></div><p><em>（共一百七十五人）</em></p><p>  （按姓氏笔划为序）</p><p>  丁关根 丁衡高 于永波（满族） 于洪恩 万 里</p><p>  万绍芬（女） 王 涛 王 海 王 蒙 王 群</p><p>  王丙乾 王汉斌 王成斌 王任重 王兆国</p><p>  王忍之 王茂林 王朝文（苗族） 王森浩 王瑞林</p><p>  毛致用 尹克升 艾知生 布 赫（蒙古族） 卢荣景</p><p>  叶选平 田纪云 史玉孝 白立忱（回族）</p><p>  司马义·艾买提（维吾尔族） 邢崇智</p><p>  吕培俭 朱 训 朱 光 朱 良 朱光亚</p><p>  乔 石 伍绍祖 伍精华（彝族） 任建新 华国锋</p><p>  全树仁 多吉才让（藏族） 刘正威 刘安元 刘振华</p><p>  刘精松 关广富（满族） 江泽民 许士杰 阮崇武</p><p>  孙维本 芮杏文 李 鹏 李九龙 李子奇</p><p>  李长春 李立功 李旭阁 李际均 李泽民</p><p>  李贵鲜 李根深 李铁映 李乾元 李梦华</p><p>  李瑞环 李锡铭 李新良 李德洙（朝鲜族）</p><p>  杨正午（土家族） 杨白冰 杨汝岱 杨析综 杨尚昆</p><p>  杨泰芳 杨静仁（回族） 杨德中 吴文英（女）</p><p>  吴官正 吴学谦 吴蔚然 何 康 何东昌</p><p>  何竹康 邹家华 沈达人 沈祖伦 宋 平</p><p>  宋 健 宋汉良 宋德福 迟浩田 张 寿</p><p>  张仲先 张勃兴 张帼英（女） 陆懋曾 陈玉英（女）</p><p>  陈光毅 陈希同 陈俊生 陈辉光 陈慕华（女）</p><p>  林 若 林丽韫（女） 罗 干 周光召 周衣冰</p><p>  周克玉 郑拓彬 房维中 赵东宛 赵先顺</p><p>  赵宗鼎 赵南起（朝鲜族） 赵紫阳 赵富林</p><p>  郝建秀（女） 胡 平 胡启立 胡锦涛 胡耀邦</p><p>  侯 捷 侯宗宾 姜春云 姜洪泉 姚依林</p><p>  贺敬之 秦仲达 秦基伟 热 地（藏族） 袁伟民</p><p>  聂奎聚 聂壁初 贾春旺 顾秀莲（女） 顾金池</p><p>  钱正英（女） 钱永昌 钱李仁 钱其琛</p><p>  铁木尔·达瓦买提（维吾尔族） 倪志福 徐惠滋</p><p>  高 狄 高焕昌 郭振乾 郭超人 郎大忠（傣族）</p><p>  戚元靖 崔乃夫 阎明复 梁步庭 梁栋材</p><p>  尉健行 彭 冲 董继昌 蒋心雄 蒋民宽</p><p>  韩培信 程维高 傅全有 普朝柱 温家宝</p><p>  谢 非 谢希德（女） 雷鸣球 鲍 彤 蔡 诚</p><p>  廖 晖 熊清泉 赛福鼎·艾则孜（维吾尔族） 薛 驹</p><p>  魏金山</p><div class="text-center"><h2 id="中央候补委员" tabindex="-1">中央候补委员 <a class="header-anchor" href="#中央候补委员" aria-label="Permalink to &quot;中央候补委员&quot;">​</a></h2></div><p><em>（共一百一十人）</em></p><p>  （以得票多少为序）</p><p>  格桑多杰（藏族） 贾志杰 马玉海（回族）</p><p>  丹 增（藏族） 王越丰（黎族）</p><p>  克尤木·巴吾东（维吾尔族） 李振潜 张连忠 陈明义</p><p>  罗尚才（布依族） 贾那布尔（哈萨克族） 王志武</p><p>  刘国光 何道泉 陈敏章 姜燮生</p><p>  马思忠（回族） 杨国梁 邹竞蒙 高镇宁</p><p>  王洛林 张立昌 赵国臣 王学珍</p><p>  尹 俊（白族） 叶连松 张万年 陈素芝（女，满族）</p><p>  葛洪升 傅锡寿 朱森林 周绍勋</p><p>  刘方仁 杨永良 陈世俊 郑 华</p><p>  钱国梁 钱绍钧 卢功勋 刘国范</p><p>  刘鸿儒 周玉书 贺国强 梁光烈</p><p>  路甬祥 王忠禹 彭功阁 朱开轩</p><p>  何光远 孙同川 宋克达 赵炳耀</p><p>  栗寿山 刘玉洁（女） 孙家正 李淑铮（女）</p><p>  林殷才 孙文盛 陈玉杰（女） 钱树根</p><p>  曾宪林 于振武 史大桢 吴邦国</p><p>  张思卿 和志强（纳西族） 徐世群</p><p>  丁廷模 栾恩杰（满族） 沙健孙（回族）</p><p>  陈至立（女） 顾传训 曾庆存</p><p>  巴图巴根（蒙古族） 廖文海（女） 刘 毅</p><p>  李慧芬（女） 韩 叙 齐怀远</p><p>  李岚清 吴 仪（女） 张彦仲</p><p>  邓鸿勋 汪家镠（女） 高德占</p><p>  刘荣惠 赵延年（回族） 金 鉴（满族）</p><p>  张万欣 董占林 朱镕基 李森茂</p><p>  任 铁 宗顺留 孙 奇 桂世镛</p><p>  邢至康（女） 胡笑云 固 辉</p><p>  白恩培 陈邦柱 周文元 赵 地（女）</p><p>  马忠臣 乔宗淮 袁 俊 何其宗</p><p>  尹长民（女） 黎 明 黄 菊</p>',77)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
